import {cartItemHTML} from './cart-item.mjs';
import {hasPersonalisation,paymentDescription,freightEstimate} from './purchase-flow.mjs';
import {paymentMethodsHTML} from './payment-methods.mjs';
import {fromInc,fromEx,quoteAmount,vatLabel,customerType} from './customer-pricing.mjs';
import {cartStatistics,sendStatistics} from './shop-statistics.mjs';
import {bindCartMockups} from './cart-mockup.mjs?v=4';
import {readJSONResponse} from './api-response.mjs';
import {loadFile} from './storage.mjs';
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const kroner=cents=>new Intl.NumberFormat('da-DK',{style:'currency',currency:'DKK'}).format(cents/100);
const key='pf-cart-v1';
export function readCart(){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value.filter(l=>l&&typeof l.id==='string'&&typeof l.productId==='string'):[];}catch{return [];}}
export function writeCart(lines,{track=true}={}){const before=track?readCart():[];localStorage.setItem(key,JSON.stringify(lines));window.dispatchEvent(new Event('pf-cart-change'));if(track){const events=cartStatistics(before,lines);if(events.length)sendStatistics(events);}}
export function putCart(line,id){const lines=readCart();if(id&&!lines.some(l=>l.id===id))throw Error('Produktet er fjernet fra kurven. Åbn det igen fra kataloget.');const result={...structuredClone(line),id:id||crypto.randomUUID()};writeCart(id?lines.map(l=>l.id===id?result:l):[...lines,result]);return result;}
export function putCartLines(items,id){
 const lines=readCart(),ids=Array.isArray(id)?id:id?[id]:[];if(ids.some(id=>!lines.some(line=>line.id===id)))throw Error('Åbn produktet igen fra kurven.');
 const added=items.map((line,index)=>({...structuredClone(line),id:ids[index]||crypto.randomUUID()}));
 writeCart(ids.length?lines.flatMap(line=>line.id===ids[0]?added:ids.includes(line.id)?[]:[line]):[...lines,...added]);return added;
}
export async function fetchQuote(lines){const r=await fetch('/api/pf-quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lines})});const result=await readJSONResponse(r,'Prisen kunne ikke hentes. Prøv igen.');if(!Array.isArray(result.lines))throw Error('Prisen kunne ikke hentes. Prøv igen.');return result;}
export function priceHTML(quote,{collapsible=false,inlineDetails=false}={}){
 if(!quote)return '<p class="small muted">Beregner pris…</p>';
 if(quote.error)return `<p class="error">${escape(quote.error)}</p>`;
 if(quote.totalIncVat===null)return `<strong>Pris afventer</strong><p class="small muted">${escape(quote.message||'Prisen er endnu ikke tilgængelig.')}</p>${quote.knownIncVat>0?`<p>Kendte varelinjer: ${kroner(fromInc(quote.knownIncVat))} ${vatLabel()}</p>`:''}`;
 return `${collapsible&&inlineDetails?`<details class="pf-line-price-details"><summary><span class="pf-cart-line-total"><strong>${kroner(quoteAmount(quote))}</strong> <span class="small muted">${vatLabel()}</span></span><span class="pf-price-details-label">Prisdetaljer</span></summary>`:collapsible?`<p class="pf-cart-line-total"><strong>${kroner(quoteAmount(quote))}</strong> <span class="small muted">${vatLabel()}</span></p>`:''}${quote.quantity&&!collapsible?`<div class="pf-quote-unit"><span>Samlet pris pr. stk. inkl. tryk og opstart</span><strong>${kroner(Math.round(quoteAmount(quote)/quote.quantity))}</strong><small>Ved ${quote.quantity} stk. · ${vatLabel()}</small></div>`:''}${collapsible&&!inlineDetails?'<details class="pf-overview-details"><summary>Prisdetaljer</summary>':''}<p class="small muted">Vare-, tryk- og opstartsbeløb er ${vatLabel()}.</p><dl class="pf-price-breakdown"><div><dt>Varer</dt><dd>${kroner(fromEx(quote.goods))}</dd></div><div><dt>Tryk</dt><dd>${kroner(fromEx(quote.print))}</dd></div>${Number.isFinite(quote.setupBase)?`<div><dt>Opstart efter evt. rabat</dt><dd>${kroner(fromEx(quote.setupBase))}</dd></div><div><dt>Småoplagstillæg</dt><dd>${kroner(fromEx(quote.smallOrder))}</dd></div>`:`<div><dt>Opstart og tillæg</dt><dd>${kroner(fromEx(quote.setup))}</dd></div>`}<div><dt>Subtotal ekskl. moms</dt><dd>${kroner(quote.net)}</dd></div><div><dt>Moms (25 %)</dt><dd>${kroner(quote.vat)}</dd></div><div class="pf-price-total"><dt>Subtotal ${vatLabel()} · ekskl. fragt</dt><dd>${kroner(quoteAmount(quote))}</dd></div>${customerType()==='business'?`<div><dt>Betaling inkl. moms</dt><dd>${kroner(quote.totalIncVat)}</dd></div>`:''}</dl><p class="small muted">Fragt og samlet pris bekræftes før betalingsreservationen.</p>${collapsible?'</details>':''}`;
}
function detailedCartOverviewHTML(data,lines,quote){
 const items=lines.map((line,index)=>{
  const product=data.products.find(p=>p.id===line.productId),variant=product?.variants.find(v=>v.sku===line.sku),price=quote.lines?.[index];
  const valid=Number.isFinite(price?.totalIncVat);
  return `<section class="pf-overview-item"><h3>${escape(product?.name||line.productId)}</h3><p class="small muted">${escape([variant?.color,variant?.size,line.sku].filter(Boolean).join(' · '))}</p><p class="small"><strong>${line.quantity} stk.</strong>${valid?` · ${kroner(Math.round(quoteAmount(price)/line.quantity))} pr. stk. ${vatLabel()}${hasPersonalisation([line])?' · inkl. tryk og opstart':' · uden tryk'}`:''}</p>${valid?`<dl class="pf-price-breakdown"><div><dt>Varer: ${line.quantity} × ${kroner(fromEx(price.goodsUnit))}</dt><dd>${kroner(fromEx(price.goods))}</dd></div></dl>${price.decorationPrices?.map(d=>`<div class="pf-overview-decoration"><strong>${escape(d.method)} · ${escape(d.position)}</strong><span>${d.colors} farve${d.colors===1?'':'r'}</span><dl class="pf-price-breakdown"><div><dt>Tryk: ${line.quantity} × ${kroner(fromEx(d.printUnit))}</dt><dd>${kroner(fromEx(d.print))}</dd></div><div><dt>Opstart efter evt. rabat</dt><dd>${kroner(fromEx(d.setup))}</dd></div>${d.smallOrder?`<div><dt>Småoplagstillæg</dt><dd>${kroner(fromEx(d.smallOrder))}</dd></div>`:''}</dl></div>`).join('')||'<p class="small muted">Uden tryk</p>'}<dl class="pf-price-breakdown"><div class="pf-price-total"><dt>Produkt i alt ${vatLabel()}</dt><dd>${kroner(quoteAmount(price))}</dd></div></dl>`:`<p class="small muted">${escape(price?.error||price?.message||'Pris afventer')}</p>`}</section>`;
 }).join('');
 return `<div class="pf-overview-items"><p class="small muted">Priser ${vatLabel()}.</p>${items}</div><h3>Samlet pris</h3>${priceHTML(quote)}`;
}
export function cartOverviewHTML(data,lines,quote,freight=null){
 const total=Number.isFinite(quote.totalIncVat)?`<dl class="pf-price-breakdown"><div class="pf-price-total"><dt>Subtotal ${vatLabel()} · ekskl. fragt</dt><dd>${kroner(quoteAmount(quote))}</dd></div></dl>`:priceHTML(quote);
 return `<p class="small muted">Priser ${vatLabel()}${hasPersonalisation(lines)?' · inkl. tryk og opstart':' · uden tryk'}.</p>${total}<p class="small muted">${freight?`Fragt ${vatLabel()}: ${kroner(fromInc(freight.incVat,freight.exVat))}`:'Fragt beregnes før betaling.'}</p><details class="pf-overview-details"><summary>Prisdetaljer</summary>${detailedCartOverviewHTML(data,lines,quote)}</details>`;
}
let headerVersion=0;
export async function updateCartHeader(){const version=++headerVersion,lines=readCart(),badge=document.querySelector('#cart-count'),sum=document.querySelector('#pf-header-sum');if(badge)badge.textContent=lines.length;if(!sum)return;if(!lines.length){sum.textContent='';return;}sum.textContent='…';try{const q=await fetchQuote(lines);if(version!==headerVersion)return;sum.textContent=q.totalIncVat===null?'Pris afventer':kroner(quoteAmount(q));}catch{if(version===headerVersion)sum.textContent='Pris afventer';}}
export function pfCartPage(data,demoCount=0){const lines=readCart();return `<section class="wrap section pf-cart-page"><nav class="purchase-path" aria-label="Købsforløb"><span class="complete"><i>✓</i><b>Produkt</b></span><span class="complete"><i>✓</i><b>${hasPersonalisation(lines)?'Design':'Valg'}</b></span><span class="active" aria-current="step"><i>3</i><b>Kurv</b></span><span><i>4</i><b>Betaling</b></span><span><i>5</i><b>${hasPersonalisation(lines)?'Korrektur':'Levering'}</b></span></nav><div class="section-heading"><div><p class="eyebrow">DINE VALG, SAMLET ÉT STED</p><h1>Din kurv <span class="title-count">${lines.length}</span></h1></div><a class="text-link" href="/">← Shop videre</a></div>${!lines.length?'<div class="empty"><a class="button" href="/">Tilbage til forsiden</a></div>':`<div class="cart-layout"><div>${lines.map(l=>{const p=data.products.find(p=>p.id===l.productId),v=p?.variants.find(v=>v.sku===l.sku);return cartItemHTML(l,p,v);}).join('')}</div><aside class="cart-summary"><h2>Dit overblik</h2><div id="pf-cart-total" aria-live="polite">Beregner pris…</div><p class="small muted">${lines.length} ${lines.length===1?'varelinje':'varelinjer'} · <span id="pf-cart-pieces">${lines.reduce((n,l)=>n+Number(l.quantity||0),0)}</span> stk.</p><a class="button wide" id="pf-cart-checkout-link" href="/betaling">Fortsæt til betaling ↗</a><p id="pf-cart-checkout-notice" class="small muted" role="status"></p>${paymentMethodsHTML}<ul class="purchase-assurances"><li>Ingen konto nødvendig</li>${hasPersonalisation(lines)?'<li>Korrektur før produktion af varer med logo</li>':''}<li>${paymentDescription(lines)}</li></ul><p class="small muted">Fragt, levering og den endelige pris vises før betalingsreservationen.</p></aside></div>`}${demoCount?`<p class="small"><a class="text-link" href="/demokurv">Se ${demoCount} tidligere demoprodukter i din tilbudskurv</a></p>`:''}</section>`;}
export function bindCart(data,nav,notify){if(!document.querySelector('.pf-cart-page'))return;let version=0;bindCartMockups(document.querySelector('.pf-cart-page'),readCart());
 async function refresh(){const current=++version,lines=readCart();try{const [q,shipping]=await Promise.all([fetchQuote(lines),Promise.all([fetch('/api/checkout/status').then(r=>readJSONResponse(r,'Betalingsstatus kunne ikke hentes.')),fetch('/api/checkout/fulfillment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lines})}).then(r=>readJSONResponse(r,'Fragt kunne ikke afklares.'))]).catch(()=>null)]);if(current!==version||!document.querySelector('#pf-cart-total'))return;document.querySelector('#pf-cart-total').innerHTML=cartOverviewHTML(data,lines,q,shipping?freightEstimate(shipping[1],shipping[0],customerType()):null);const checkoutLink=document.querySelector('#pf-cart-checkout-link'),notice=document.querySelector('#pf-cart-checkout-notice');if(checkoutLink&&notice){const unavailable=shipping&&!shipping[1].ready;checkoutLink.href=unavailable?'/kontakt':'/betaling';checkoutLink.textContent=unavailable?'Kontakt os om bestillingen →':shipping&&!shipping[0].ready?'Se bestillingsstatus →':'Fortsæt til betaling ↗';notice.textContent=unavailable?shipping[1].message:shipping&&!shipping[0].ready?(shipping[0].launch?.ordersEnabled===false?'Webshoppen er endnu ikke åben for bestillinger.':'Bestilling afventer afklaring. Kontakt os, hvis du vil bestille nu.'):'Fragt lægges til subtotalen før betaling.';}for(const [i,l]of lines.entries()){const row=[...document.querySelectorAll('[data-pf-line]')].find(el=>el.dataset.pfLine===l.id);if(row)row.querySelector('[data-pf-line-price]').innerHTML=priceHTML(q.lines[i],{collapsible:true,inlineDetails:true});}}catch(error){if(current===version&&document.querySelector('#pf-cart-total')){document.querySelector('#pf-cart-total').textContent=error.message;document.querySelectorAll('[data-pf-line-price]').forEach(el=>el.textContent='Pris afventer');}}}
 document.querySelectorAll('[data-pf-quantity]').forEach(input=>input.onchange=()=>{const quantity=Number(input.value),lines=readCart(),line=lines.find(l=>l.id===input.dataset.pfQuantity),error=input.closest('.pf-cart-item').querySelector('[data-pf-line-error]');if(!Number.isInteger(quantity)||quantity<1||quantity>100000){error.textContent='Vælg mellem 1 og 100.000 stk.';input.value=line.quantity;return;}try{writeCart(lines.map(l=>l.id===line.id?{...l,quantity}:l));error.textContent='';document.querySelector('#pf-cart-pieces').textContent=readCart().reduce((n,l)=>n+l.quantity,0);refresh();}catch{error.textContent='Kurven kunne ikke gemmes.';input.value=line.quantity;}});
 document.querySelectorAll('[data-pf-remove]').forEach(button=>button.onclick=()=>{try{writeCart(readCart().filter(l=>l.id!==button.dataset.pfRemove));nav('/kurv');notify('Produktet er fjernet fra kurven.');}catch{notify('Kurven kunne ikke gemmes.');}});
 document.querySelectorAll('[data-pf-logo]').forEach(button=>button.onclick=async()=>{const file=await loadFile(button.dataset.pfLogo);if(!file){notify('Logofilen mangler. Åbn designet og upload igen.');return;}download(file,button.dataset.name);});
 const root=document.querySelector('.pf-cart-page');const onPricingChange=()=>{if(!root.isConnected){window.removeEventListener('customer-pricing-change',onPricingChange);return;}refresh();};window.addEventListener('customer-pricing-change',onPricingChange);refresh();
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
